<style>
    /*Setting Pag Card Effects*/
    .setting-box {
        position: relative;
        /* background: var(--body-bg); */
        color: #fff;
        display: flex;
        flex-direction: column;
        padding: 50px 30px;
        height: 100%;
        /* border-radius: 20px; */
        justify-content: center;
        align-items: center;
        gap: 20px;
        transition: all 0.5s;
        overflow: hidden;
        box-shadow: 0px 0px 230px 0px #0000001A;
    }
    .setting-box h5 {
        color: var(--black-color);
    }
    .setting-box .bg {
        position: absolute;
        display: block;
        width: 0;
        height: 0;
        border-radius: 50%;
        background: var(--theme-br2);
        transition: width 0.4s ease-in-out, height 0.4s ease-in-out;
        transform: translate(-50%, -50%);
        z-index: -1;
    }
    .setting-box:hover {
        transform: translateY(-6px);
    }
    .setting-box h5 {
        transition: all 0.5s;
        color: var(--primary-color);
        font-size: 14px;
        font-weight: 400;
    }
    .setting-box:hover h5,
    .setting-box:hover .setting-icon {
        color: var(--primary-color);
        svg path {
            fill: var(--primary-color);
        }
    }
    .setting-box:hover .bg {
        width: 225%;
        height: 562.5px;
    }
    .setting-box .setting-icon {
        font-size: 60px;
        text-align: center;
        color: var(--primary-color);
        display: flex;
        align-items: center;
        justify-content: center;
        svg path{
            transition: all 0.5s; 
        }
    }
</style>
